def components(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                v=g[i][j]; st=[(i,j)]; cells=set()
                while st:
                    y,x=st.pop()
                    if (y,x) in cells: continue
                    cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==v and (ny,nx) not in cells: st.append((ny,nx))
                res.append((v,cells))
    return res

def solve(g):
    H,W=len(g),len(g[0])
    comps=components(g)
    # floor: component whose bounding box spans full width (a complete row)
    floor=None
    for v,cs in comps:
        ys=[r for r,_ in cs]
        if min(ys)==max(ys) and len(cs)==W: floor=(v,cs); break
    assert floor
    fv,fset=floor
    # gravity direction: toward floor side (if floor at bottom -> down, else up)
    frow=min(r for r,_ in fset); fcol=max(c for _,c in fset)
    down = (frow==H-1)
    # order: process by max row distance from floor (farthest first), i.e. bottom-most first when floor at bottom
    others=[(v,cs) for v,cs in comps if cs!=fset]
    def key(cs):
        return max(r for r,_ in cs) if down else min(r for r,_ in cs)
    others.sort(key=key, reverse=down)
    occ=set(fset); grid=[row[:] for row in g]
    for v,cs in others:
        # displacement vector
        dy=1 if down else -1
        d=0
        while True:
            nxt={(r+dy*d, c) for r,c in cs}
            if any(p in occ or not(0<=p[0]<H and 0<=p[1]<W) for p in nxt): break
            d+=1
        for (r,c) in cs:
            grid[r+d*dy][c]=v
            occ.add((r+d*dy,c))
    return grid

