def f(g, vert=True):
    H,W=len(g),len(g[0])
    bg=max(set(v for row in g for v in row), key=lambda v:sum(row.count(v) for row in g))
    bandc=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=bg]
    bandr=[r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg]
    bandcells={(r,c) for r in range(H) for c in range(W)}
    for r in bandr:
        for c in range(W): bandcells.add((r,c))
    for c in bandc:
        for r in range(H): bandcells.add((r,c))
    comps=get_comps(g,bg,bandcells)
    placed=set(); grid=[[bg]*W for _ in range(H)]
    if vert and len(bandc)==1:
        b=bandc[0]; order=sorted(comps,key=lambda c:-max(j for _,j in c))
        for comp in order:
            k=1
            while True:
                bad=False
                for i,j in comp:
                    if j+k>=b or ((i,j+k) in placed): bad=True;break
                if bad: break
                k+=1
            kk=k-1
            for i,j in comp: grid[i][j+kk]=g[i][j]; placed.add((i,j+kk))
        bandcol=[g[0][b]]; [grid[r][b]+=0 for r in range(H)]
        for r in range(H): grid[r][b]=bandcol[0]
    else:
        b=bandr[0]; order=sorted(comps,key=lambda c:min(i for i,_ in c))
        for comp in order:
            k=1
            while True:
                bad=False
                for i,j in comp:
                    if i-k<b or ((i-k,j) in placed): bad=True;break
                if bad: break
                k+=1
            kk=k-1
            for i,j in comp: grid[i-kk][j]=g[i][j]; placed.add((i-kk,j))
    # restore band
    bandv=g[bandr[0]][0] if bandr else g[0][bandc[0]]
    if bandr:
        for c in range(W): grid[bandr[0]][c]=bandv
    else:
        for r in range(H): grid[r][bandc[0]]=bandv
    return grid
