def comps(g,val):
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        y2,x2=y+dy,x+dx
                        if 0<=y2<H and 0<=x2<W and g[y2][x2]==val and (y2,x2) not in seen:
                            seen.add((y2,x2)); st.append((y2,x2))
                res.append(c)
    return res
