# Test: objects slide right until touching another object or the border color column, processing order bottom-to-top by min row; blocking only on placed.
from collections import Counter
def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and g[i][j]!=2 and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]; v=g[i][j]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        y2,x2=y+dy,x+dx
                        if 0<=y2<H and 0<=x2<W and g[y2][x2]==v and (y2,x2) not in seen:
                            seen.add((y2,x2)); st.append((y2,x2))
                res.append((v,c))
    return res
def solve(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    objs=comps_of(g,bg)
    objs.sort(key=lambda o:(o[1][0][0], max(x for _,x in o[1])))
    res=[[bg]*W for _ in range(H)]
    occ=set()
    for v,cc in objs:
        cur=list(cc)
        while True:
            nxt=[(y,x+1) for y,x in cur]
            if any(x>=W or (res[y][x] in (2,) or res[y][x]!=bg and (y,x) not in set(cur)) or (y,x) in occ for y,x in nxt): break
            cur=nxt
        for y,x in cur: res[y][x]=v; occ.update(cur)
    return res
